// ============================================================================
// Detection: ClusterRoleBinding / RoleBinding Creation by Non-System Principal
// MITRE ATT&CK: T1098.006 - Additional Container Cluster Roles
// Source: AKSAudit
// ============================================================================
//
// Logic: RBAC binding creation outside CI/CD or system controllers is rare and
// almost always suspicious. In a production cluster you'd add Argo/Flux/Helm
// controllers to the exclusion list — for the lab, only K8s system controllers
// are excluded.
//
// This is the DETECTION half of the T1098.006 bundle. attack.sh creates a
// ClusterRoleBinding; the API server logs that write to AKSAudit; this query finds
// it; rule.bicep runs this query on a schedule as a Sentinel alert.

AKSAudit
| where TimeGenerated > ago(1h)                       // recent window first
| where Stage == "ResponseComplete"                   // one audit event has multiple stages; keep the final one so we don't double-count
| where Verb in ("create", "update", "patch")         // any mutation that could establish a binding
| extend                                              // extend = compute new columns by flattening the nested audit JSON:
    Username     = tostring(User.username),            //   who made the call
    Resource     = tostring(ObjectRef.resource),       //   what kind of object
    Namespace    = tostring(ObjectRef.namespace),      //   its namespace (empty for cluster-scoped)
    BindingName  = tostring(ObjectRef.name),           //   the binding's name
    ResponseCode = toint(ResponseStatus.code),         //   HTTP status the API server returned
    SourceIp     = tostring(SourceIps[0])              //   caller IP (first in the list)
| where Resource in ("clusterrolebindings", "rolebindings")  // only RBAC binding objects
| where ResponseCode between (200 .. 299)             // only calls that actually SUCCEEDED (2xx)
// Exclude stable system actors — kube-system SAs, node kubelets, and the built-in
// controller-manager legitimately create bindings; alert on everyone else.
| where not(Username startswith "system:serviceaccount:kube-system:")
| where not(Username startswith "system:node:")
| where Username != "system:kube-controller-manager"
| project                                             // keep just the columns an analyst needs
    TimeGenerated, Username, Verb, Resource, BindingName, Namespace,
    SourceIp, UserAgent
| extend MitreTechnique = "T1098.006"    // tag hits with the ATT&CK sub-technique

variables.$fxv#1:
// ============================================================================
// Detection: Privileged Pod Creation
// MITRE ATT&CK: T1610 - Deploy Container
// Source: AKSAuditAdmin
// ============================================================================

// HOW THIS DETECTION WORKS
// -------------------------
// A container with securityContext.privileged=true runs with all capabilities and
// effectively unrestricted access to the host — the easiest breakout there is. An
// attacker who can create pods deploys a privileged one to gain a foothold on the
// node (T1610 Deploy Container). This fires at admission (pod `create`).
//
// Two mechanics matter:
//   1. A privileged container can hide in ANY of three lists — containers,
//      initContainers, ephemeralContainers — so we array_concat all three into one
//      list before scanning. coalesce(..., dynamic([])) turns a missing list into
//      an empty array so the concat never fails on nulls.
//   2. mv-apply then checks EACH container, so a single privileged sidecar is
//      caught and reported BY NAME (not just "the pod had something privileged").
//
// TABLE: AKSAuditAdmin — write/mutating audit events (pod `create`).

AKSAuditAdmin
| where TimeGenerated > ago(1h)                                  // recent window first
| where Verb == "create" and ObjectRef.resource == "pods"       // only pod-creation events
// Merge the three possible container lists into one array to scan uniformly.
// coalesce() supplies an empty array when a given list is absent (null-safe concat).
| extend allContainers = array_concat(
    coalesce(RequestObject.spec.containers,          dynamic([])),   // normal app containers
    coalesce(RequestObject.spec.initContainers,      dynamic([])),   // init containers
    coalesce(RequestObject.spec.ephemeralContainers, dynamic([])))   // debug/ephemeral containers
// Expand to one row per container; keep only those explicitly marked privileged.
| mv-apply container = allContainers on (
    where container.securityContext.privileged == true   // null-safe: unset != true
    | project ContainerName = tostring(container.name), Image = tostring(container.image)  // name + image of the offender
  )
// Tune: AKS system DaemonSets (kube-proxy, CSI node drivers) are legitimately
// privileged — allowlist kube-system controllers, alert on everyone else.
| where User.username != "aksService" and User.username !startswith "system:"  // drop AKS + control-plane creators
| project TimeGenerated, User = tostring(User.username), ClientIp = tostring(SourceIps[0]),   // who + from where
          Namespace = tostring(ObjectRef.namespace), Pod = tostring(ObjectRef.name),           // which pod
          ContainerName, Image, RequestUri                                                     // which container + image
| extend MitreTechnique = "T1610"    // tag with the ATT&CK technique

variables.$fxv#11:
// ============================================================================
// Detection: Client Certificate Credential via CSR (Self-Approved)
// MITRE ATT&CK: T1098 - Account Manipulation
// Source: AKSAuditAdmin
// ============================================================================

// HOW THIS DETECTION WORKS
// -------------------------
// Kubernetes lets you request a signed client certificate through the
// CertificateSigningRequest (CSR) API: you `create` a CSR, then someone with
// rights `update`s its /approval subresource, and the cluster CA signs it. A
// signed client cert authenticates to the API server as whatever user/groups
// the CSR named — so a self-approved CSR is a way to MINT durable credentials
// (T1098 Account Manipulation / credential creation).
//
// The strong signal here is a SEPARATION-OF-DUTY violation: the SAME principal
// both creates the CSR and approves it. Legitimate flows split requester from
// approver (kubelet requests, certificate-controller approves).
//
// TABLE: AKSAuditAdmin — the "admin" slice of the Kubernetes audit log. It keeps
//        WRITE/mutating events (create/update/delete) but not routine reads, so
//        it is the right, cheaper table for approval-workflow tampering.

AKSAuditAdmin
| where TimeGenerated > ago(1h)                                       // prune to the recent window first
| where ObjectRef.resource == "certificatesigningrequests"           // only CSR API objects
// Keep BOTH halves of the flow: the initial create, AND updates that hit the
// /approval subresource (the moment a CSR is signed off). Either alone is noise;
// the pair from one user is the finding.
| where (Verb == "create") or (Verb == "update" and ObjectRef.subresource == "approval")
// Tune: kubelets create CSRs and certificate-controller approves them — both system:*.
| where User.username !startswith "system:"                          // drop built-in control-plane actors
| project TimeGenerated, User = tostring(User.username), Verb,       // project = keep just these columns...
          Sub = tostring(ObjectRef.subresource), CSR = tostring(ObjectRef.name), RequestUri
| sort by TimeGenerated asc   // create then approval from one user = self-signed credential
| extend MitreTechnique = "T1098"    // tag hits with the ATT&CK technique

variables.$fxv#13:
// ============================================================================
// Detection: Container Escape via nsenter
// MITRE ATT&CK: T1611 - Escape to Host
// Source: AKSAudit + ContainerLogV2
// ============================================================================

// HOW THIS DETECTION WORKS
// -------------------------
// `nsenter` enters another process's Linux namespaces. Inside a privileged
// container an attacker runs `nsenter --target 1 --mount ...` to jump into the
// HOST's namespaces (PID 1 = the node's init) and effectively break out of the
// container onto the node — that is T1611 (Escape to Host).
//
// This query is LOG/STDOUT-based: it scans container stdout/stderr captured in
// Log Analytics for the literal string "nsenter". It is the cheap, always-on
// complement to the Falco syscall rule (detections/falco/container-escape.yaml),
// which catches the actual process spawn at the kernel level.
//
// TABLE: ContainerLogV2 — the Azure Monitor for Containers table holding one row
//        per container stdout/stderr line, enriched with pod/namespace metadata.

ContainerLogV2                       // read collected container console logs
| where TimeGenerated > ago(1h)      // time filter first (cheapest, prunes the scan window)
| where LogMessage has "nsenter"     // `has` = whole-token match on the log text; the escape tell
| project TimeGenerated, PodName, PodNamespace, ContainerName, LogMessage  // keep only the analyst-relevant columns
| extend MitreTechnique = "T1611"    // tag every hit with the ATT&CK technique for triage/reporting

variables.$fxv#15:
// ============================================================================
// Detection: Cryptocurrency Mining in Container
// MITRE ATT&CK: T1496 - Resource Hijacking
// Source: ContainerLogV2 + InsightsMetrics
// ============================================================================

// HOW THIS DETECTION WORKS
// -------------------------
// Crypto mining (T1496 Resource Hijacking) steals the cluster's CPU to mine coins.
// There are two complementary ways to catch it, and this file ships both:
//
//   1. PROCESS/SIGNATURE (active below): scan container logs for the fingerprints
//      of miners — binary names (xmrig, minerd), mining-pool protocol strings
//      (stratum+tcp), algorithm names (cryptonight), and known pool hostnames.
//   2. CPU ANOMALY (commented out): watch resource metrics for sustained high CPU,
//      which catches unknown/renamed miners that leave no signature.
//
// The signature approach is precise (low false positives) but misses novel miners;
// the anomaly approach is the safety net. In production you'd run both.

// --- Approach 1: signature match on container stdout/stderr -------------------
// TABLE: ContainerLogV2 — collected container console output.
ContainerLogV2
| where TimeGenerated > ago(1h)          // recent window first
// has_any = match if the log line contains ANY of these tokens. Mix of binary
// names, pool-protocol markers, and a known pool hostname — the miner's fingerprints.
| where LogMessage has_any ("xmrig", "minerd", "stratum+tcp", "cryptonight", "pool.minexmr")
| project TimeGenerated, PodName, PodNamespace, ContainerName, LogMessage  // analyst-relevant columns
| extend MitreTechnique = "T1496"        // tag with the ATT&CK technique

// --- Approach 2: CPU anomaly (DISABLED — reference implementation) ------------
// Enable when signature coverage isn't enough; catches renamed/unknown miners.
// TABLE: InsightsMetrics — the Azure Monitor container metrics table.
// InsightsMetrics
// | where TimeGenerated > ago(1h)
// | where Namespace == "container.azm.ms/cpu"        // the CPU metric namespace
// | where Name == "cpuUsageNanoCores"                // per-container CPU usage counter
// | extend Tags = parse_json(Tags)                   // Tags is JSON; parse to read podName/podNamespace
// | where todouble(Val) > 1800000000 // >1.8 cores sustained = suspicious
// | project TimeGenerated, PodName = tostring(Tags.podName), Namespace = tostring(Tags.podNamespace), CpuNanoCores = Val

variables.$fxv#17:
// ============================================================================
// Detection: Lateral Movement via Cross-Namespace Token Use
// MITRE ATT&CK: T1550.001 - Application Access Token
// Source: AKSAudit
// ============================================================================

// HOW THIS DETECTION WORKS
// -------------------------
// A ServiceAccount identity is namespaced: its username has the shape
// `system:serviceaccount:<namespace>:<name>`. Normally a workload's SA only ever
// touches resources in its OWN namespace. When an SA from namespace A starts
// acting on resources in namespace B, that's a strong lateral-movement signal —
// the attacker stole a token in A and is reusing it to reach into B
// (T1550.001 Use Alternate Authentication Material: Application Access Token).
//
// The core trick: derive the SOURCE namespace from the SA username, compare it to
// the TARGET namespace on the object being accessed, and alert when they differ.
//
// TABLE: AKSAudit — the full audit log (we need reads: get/list, not just writes).

AKSAudit
| where TimeGenerated > ago(1h)                          // recent window first
| where Verb in ("get", "list", "create", "exec")        // read/create/exec — the actions worth tracking
| extend Username = tostring(User.username)               // pull the caller identity out as a string
// extract() runs a regex and returns capture group 1: the namespace embedded in a
// ServiceAccount username. For a non-SA (a human/AAD user) there's no match -> "".
| extend SourceNamespace = extract("system:serviceaccount:([^:]+):", 1, Username)
| extend TargetNamespace = tostring(ObjectRef.namespace)  // the namespace of the object being touched
| where isnotempty(SourceNamespace)                       // keep only ServiceAccount callers
| where isnotempty(TargetNamespace)                       // keep only namespaced target objects
| where SourceNamespace != TargetNamespace                // THE FINDING: cross-namespace access
| project TimeGenerated, Username, SourceNamespace, TargetNamespace, Verb, Resource = tostring(ObjectRef.resource)  // who went where, doing what
| extend MitreTechnique = "T1550.001"    // tag with the ATT&CK sub-technique

